const seo23=["Her sayfanın özgün başlığı","Açıklayıcı meta açıklama","Her sayfada tek H1","H1, H2, H3 başlık hiyerarşisi","Kısa ve anlaşılır URL","URL'de Türkçe karakter ve gereksiz parametre olmaması","Anahtar kelimenin doğal kullanımı","Yinelenen içeriğin önlenmesi","Canonical etiketi","robots.txt kontrolü","XML sitemap oluşturma ve gönderme","Google Search Console bağlantısı","İndeksleme kontrolü","Bozuk bağlantıların düzeltilmesi","Faydalı 404 sayfası","Eski URL'ler için doğru 301 yönlendirmesi","Açıklayıcı görsel alt metni","Görsellerin sıkıştırılması ve doğru boyut","Mobil görünüm","Sayfa hızı ve yavaş kaynaklar","HTTPS","İlgili sayfalar arası iç bağlantılar","Uygun Schema markup"];
const seo20=["Google'da site adını ara","Önemli sayfaların başlığını kontrol et","Arama sonucundaki açıklamayı kontrol et","Mobilde sayfaları gez","Yavaş bağlantıda aç","Gizli sekmede aç","Menü bağlantılarını dene","Footer bağlantılarını dene","Form gönder ve sonucu incele","Olmayan URL'de 404'ü aç","Eski URL yönlendirmelerini dene","Görseller yüklenmeden sayfayı oku","Her sayfada tek H1'i doğrula","URL'leri incele","Canonical URL'leri incele","Sitemap'i tarayıcıda aç","robots.txt'yi aç","Search Console indeks raporunu aç","Lighthouse veya PageSpeed ile ölç","Başka birine ver ve aradığını buluşunu izle"];
const security=["API anahtarlarını koddan çıkar"," .env dosyasını Git geçmişinden temizle","İzin kurallarını açıkça yaz","Yetki kontrolünü sunucuda uygula","Giriş denemelerini sınırla","Tüm girdileri doğrula","Dosya yükleme boyutu ve türünü sınırla","CORS izinlerini daralt","Güvenlik başlıklarını ayarla","HTTPS'yi zorunlu kıl","Şifreleri güçlü algoritmayla hash'le","Çerezleri Secure, HttpOnly ve SameSite yap","Hata mesajlarından iç ayrıntıları çıkar","Loglarda gizli verileri temizle","Veritabanı sorgularını parametrele","Çıktıyı XSS'e karşı kaçır","Webhook imzasını doğrula","Admin işlemlerini rolle sınırla","Paketleri güvenlik açısından denetle","Otomatik yedek kur","Hesap silme akışını gerçekten tamamla","Harcama uyarıları kur","Saldırgan bakışıyla test et"];
const mobile=["Uçak modunda kullan","Soğuk açılış süresini ölç","Karanlık modda gez","En büyük yazı boyutunda kullan","Her giriş alanında klavyeyi dene","Yeni kurulum gibi ilk açılışı dene","Her ekranda geri tuşunu dene","Ekranı yatay çevir","Silme işlemi ve onayını dene","İnterneti kesip kayıt yap","Tüm hata metinlerini oku","İzin gerekçelerini incele","Hesap silmeyi dene","Ödeme ekranı metnini incele","Kapatma tuşunu bul","Şarjdan çıkarıp on dakika kullan","Depolama kullanımını ölç","Telefonun dilini değiştir","Yönlendirme yapmadan başkasına ver","Silip yeniden kur"];
let currentList="seo23", data=null, filter="all";
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function drawList(el,arr,kind){
 const scope=data?.url||'genel',saved=readStore('rogi-checklists-v1',{}),state=saved[scope]||{};
 document.getElementById(el).innerHTML=arr.map((title,i)=>{const key=kind+':'+(el==='seo-list'?currentList:el)+':'+i,entry=state[key]||{},value=['unknown','pass','fail','na'].includes(entry.status)?entry.status:'unknown';return '<details><summary>'+escapeHTML(title)+'</summary><label>Durum <select aria-label="Kontrol durumu" data-check="'+escapeHTML(key)+'">'+[['unknown','Doğrulanamadı'],['pass','Geçti'],['fail','Düzeltilecek'],['na','Uygulanamaz']].map(([v,label])=>'<option value="'+v+'"'+(v===value?' selected':'')+'>'+label+'</option>').join('')+'</select></label><label>Not ve kanıt <textarea aria-label="Not ve kanıt" maxlength="2000" data-note="'+escapeHTML(key)+'" placeholder="Dosya/satır, test edilen akış veya gözleminiz">'+escapeHTML(entry.note||'')+'</textarea></label></details>';}).join('');
}

function view(name){document.querySelectorAll(".section").forEach(x=>x.classList.toggle("active",x.id===name));document.querySelectorAll(".nav button").forEach(x=>x.classList.toggle("active",x.dataset.view===name));document.getElementById("main-title").textContent=({site:"Site analizi",project:"Geliştirme projesi",seo:"SEO kontrol listesi",security:"Uygulama güvenliği",mobile:"Mobil kullanım testleri"})[name];document.getElementById("main-title").focus();}
document.querySelectorAll(".nav button").forEach(x=>x.onclick=()=>view(x.dataset.view));
function syncSelectionStates(){document.querySelectorAll('.nav button').forEach(b=>{b.setAttribute('aria-pressed',String(b.classList.contains('active')));b.setAttribute('aria-controls',b.dataset.view);});document.querySelectorAll('[data-filter],[data-list]').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('active'))));}
